Shared contracts exist for the booking context and the external payments context. In the booking context, `aggregate "booking" { identity = field_type.booking_id }` and `deposit_recorded` has the fields booking_id, payment_reference, and amount. The payments context is:

```hcl
bounded_context "payments" {
  external = true

  event "payment_received" {
    field "booking_reference" {
      type            = "String"
      correlation_key = true
    }
    field "payment_reference" {
      type              = "String"
      deduplication_key = true
    }
    field "paid_amount" {
      type = "Decimal"
    }
  }
}
```

Generate the Dart code for this workflow:

```hcl
automation "record_deposit" {
  processor "deposit_translator" {
    from = [event.payments.payment_received]
    to   = [command.record_deposit]

    field "payment_reference" {
      type = field_type.booking.payment_reference
    }
  }

  command "record_deposit" {
    aggregate = aggregate.booking.booking
    fields    = [field_type.booking.booking_id, field_type.booking.payment_reference, field_type.booking.amount]
    to        = [event.booking.deposit_recorded]
  }

  field_source {
    inputs = [event.payments.payment_received.field.payment_reference]
    target = processor.deposit_translator.field.payment_reference
  }

  scenario "payment_becomes_deposit" {
    case = "happy_path"
    given { event = event.payments.payment_received }
    when  { processor = processor.deposit_translator }
    then  { command = command.record_deposit }
  }

  scenario "repeated_payment_is_ignored" {
    case = "business_duplicate"
    given { event = event.booking.deposit_recorded }
    given { event = event.payments.payment_received }
    when  { processor = processor.deposit_translator }
    then {
      expect_no_dispatch = true
      command            = command.record_deposit
    }
  }
}
```

Shared contracts exist for the appointments context (events appointment_added and appointment_reminder_requested, both with the field appointment_id). Generate the Dart code for this workflow:

```hcl
automation "request_appointment_reminder" {
  readmodel "appointments_needing_reminder" {
    question = "Which added appointments still need a reminder?"
    fields   = [field_type.appointments.appointment_id]
    from = [
      event.appointments.appointment_added,
      event.appointments.appointment_reminder_requested,
    ]
    to = [processor.reminder_processor]
  }

  processor "reminder_processor" {
    to = [command.request_reminder]
  }

  command "request_reminder" {
    fields = [field_type.appointments.appointment_id]
    to     = [event.appointments.appointment_reminder_requested]
  }

  scenario "reminder_is_requested" {
    given { readmodel = readmodel.appointments_needing_reminder }
    when  { processor = processor.reminder_processor }
    then  { event = event.appointments.appointment_reminder_requested }
  }

  scenario "no_appointment_yet" {
    empty_history = true
    then {
      expect_empty_list = true
      readmodel         = readmodel.appointments_needing_reminder
    }
  }

  scenario "added_appointment_needs_reminder" {
    case = "appear"
    given { event = event.appointments.appointment_added }
    then  { readmodel = readmodel.appointments_needing_reminder }
  }

  scenario "reminded_appointment_leaves_the_list" {
    case = "disappear"
    given { event = event.appointments.appointment_added }
    given { event = event.appointments.appointment_reminder_requested }
    then {
      expect_empty_list = true
      readmodel         = readmodel.appointments_needing_reminder
    }
  }
}
```
